-- Generated by node scripts/prepare-catalog-release.mjs; review the source JSON.
-- Run ONCE in the existing Supabase SQL Editor AFTER deploying the new images.
-- Keeps existing product/variant IDs, orders, costs, categories and uploaded photos.
-- Client stock replaces sample quantities. Active reservations abort the ENTIRE import.
-- Unconfirmed photo/price matches remain private drafts. No payment settings change.
-- A repeated successful batch is a no-op, so it cannot reset later stock/admin edits.
begin;
create table if not exists seen_private.catalog_import_backups (
  batch text primary key,
  snapshot jsonb not null,
  created_at timestamptz not null default now()
);
alter table seen_private.catalog_import_backups enable row level security;
revoke all on seen_private.catalog_import_backups from public, anon, authenticated;

do $import$
declare
  release jsonb := $catalog${"batch":"catalog-intake-20261020-v1","stockNote":"Client-approved prices and photo matches, 20 October 2026. Only Burgundy Roselle has stock: 54 x 1, 56 x 1, 58 x 2. All other designs are visible but sold out. Available size labels are 54, 56 and 58.","sizes":["54","56","58"],"products":[{"id":"design-01","name":"Burgundy Roselle Edit","tone":"Burgundy","pricePence":4500,"ready":true,"description":"Deep burgundy tones meet a flowing, full-length silhouette in the Roselle Edit. Covered buttons and softly flared sleeves bring a considered finish, creating an elegant piece for everyday dressing and special occasions alike.","stock":{"54":1,"56":1,"58":2},"photos":[{"src":"/images/products/design-01/front.webp","label":"Front","alt":"Front view of a burgundy abaya with a matching scarf."},{"src":"/images/products/design-01/back.webp","label":"Back","alt":"Back view of the burgundy abaya against ivory studio draping."},{"src":"/images/products/design-01/detail.webp","label":"Details","alt":"Covered buttons and sleeve details on the burgundy abaya."},{"src":"/images/products/design-01/alternate.webp","label":"Another angle","alt":"Another front view of the burgundy abaya."}]},{"id":"design-02","name":"Black Sequin Abaya","tone":"Black","pricePence":5000,"ready":true,"description":"Tonal botanical sequin detailing traces a black, full-length silhouette, adding subtle definition to the front and sleeves. The flowing shape gives this piece an understated presence, with its detail revealed up close.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-02/front.webp","label":"Front","alt":"Black abaya with tonal botanical details on the front and sleeves."},{"src":"/images/products/design-02/back.webp","label":"Back","alt":"Back view of the black abaya with tonal botanical details."}]},{"id":"design-03","name":"Black Lace Abaya","tone":"Black","pricePence":5000,"ready":true,"description":"A black silhouette framed by delicate lace detailing along the opening and sleeves. The full-length shape and contrasting textures create a refined statement that moves easily from considered daytime styling to an evening occasion.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-03/front.webp","label":"Front","alt":"Black abaya with lace detailing along the opening and sleeves."},{"src":"/images/products/design-03/detail.webp","label":"Details","alt":"Closer view of the black abaya's lace sleeve and front details."}]},{"id":"design-04","name":"Teal Abaya","tone":"Teal","pricePence":4000,"ready":true,"description":"Rich teal tones, covered buttons and gently flared sleeves define this full-length abaya. Its simple, flowing silhouette makes room for personal styling, offering quiet elegance with an uncluttered finish.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-04/front.webp","label":"Front","alt":"Front view of a plain teal abaya with covered buttons."},{"src":"/images/products/design-04/styled.webp","label":"Styled view","alt":"Seated view of the teal abaya with a matching scarf."}]},{"id":"design-05","name":"Tie Dye Blue Abaya","tone":"Blue","pricePence":4000,"ready":true,"description":"A blue tie-dye pattern brings depth to a flowing, full-length silhouette. The simple neckline and wide sleeves allow the pattern to take the lead, creating a distinctive piece with an understated finish.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-05/front.webp","label":"Front","alt":"Blue tie-dye abaya with a flowing shape and wide sleeves."}]},{"id":"design-06","name":"Polka Dot Abaya","tone":"Black","pricePence":4500,"ready":true,"description":"Ivory polka dots punctuate a black, full-length silhouette for a playful take on everyday elegance. The flowing shape and wide sleeves keep the overall look relaxed and considered, with the print providing its distinctive character.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-06/front.webp","label":"Front","alt":"Black abaya and matching scarf with ivory polka dots."},{"src":"/images/products/design-06/styled.webp","label":"Styled view","alt":"Seated campaign view of the black and ivory polka-dot abaya."}]},{"id":"design-07","name":"Cream Abaya","tone":"Cream","pricePence":4500,"ready":true,"description":"Soft cream tones, covered buttons and a flowing, full-length shape create an understated foundation for your wardrobe. The clean silhouette and gently flared sleeves make this an elegant piece to style in your own way.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-07/front.webp","label":"Front","alt":"Full-length mirror photograph of a cream abaya and scarf."},{"src":"/images/products/design-07/detail.webp","label":"Details","alt":"Close view of the cream abaya's covered buttons and sleeve."}]},{"id":"design-08","name":"Brown Abaya","tone":"Brown","pricePence":4000,"ready":true,"description":"Rich brown tones, covered buttons and wide sleeves create a flowing silhouette with understated detail. An easy foundation for a considered everyday look, this full-length piece brings warmth and simplicity to your styling.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-08/front.webp","label":"Front","alt":"Full-length front view of a brown abaya with covered buttons and wide sleeves."},{"src":"/images/products/design-08/detail.webp","label":"Details","alt":"Closer view of the brown abaya neckline, covered buttons and sleeve."},{"src":"/images/products/design-08/styled.webp","label":"Styled view","alt":"Seated view showing the drape of the brown abaya."},{"src":"/images/products/design-08/alternate.webp","label":"Another angle","alt":"Lifestyle view of the brown abaya worn while seated."}]},{"id":"design-09","name":"Olive Abaya","tone":"Olive","pricePence":4000,"ready":true,"description":"An olive silhouette with covered buttons and wide sleeves. The simple lines and flowing, full-length shape bring quiet elegance to everyday dressing, with a rich colour that lends itself to considered, individual styling.","stock":{"54":0,"56":0,"58":0},"photos":[{"src":"/images/products/design-09/front.webp","label":"Front","alt":"Front view of an olive abaya with covered buttons and wide sleeves."},{"src":"/images/products/design-09/detail.webp","label":"Details","alt":"Closer view of the olive abaya sleeve and button detailing."},{"src":"/images/products/design-09/styled.webp","label":"Styled view","alt":"Seated view of the olive abaya showing its flowing shape."}]}]}$catalog$::jsonb;
  item jsonb; extra jsonb; size_value text; pid uuid; vid uuid;
  photo_list jsonb; existing_photos jsonb; position_value integer;
begin
  lock table public.products, public.product_variants, seen_private.inventory in share row exclusive mode;
  if exists(select 1 from seen_private.catalog_import_backups where batch=release->>'batch') then
    raise notice 'This catalogue batch was already applied. No products or stock changed.';
    return;
  end if;
  if exists (
    select 1 from seen_private.inventory i
    join public.product_variants v on v.id=i.variant_id
    join public.products p on p.id=v.product_id
    where i.reserved>0 and p.design_reference in (select value->>'id' from jsonb_array_elements(release->'products'))
  ) then
    raise exception 'Catalogue update stopped: finish/cancel open test checkouts first, or refresh expired payment statuses in Admin > Orders. Reservations were not changed.';
  end if;
  insert into seen_private.catalog_import_backups(batch,snapshot)
  select release->>'batch',jsonb_build_object(
    'products',coalesce((select jsonb_agg(to_jsonb(p)) from public.products p where p.design_reference in (select value->>'id' from jsonb_array_elements(release->'products'))),'[]'::jsonb),
    'variants',coalesce((select jsonb_agg(to_jsonb(v)) from public.product_variants v join public.products p on p.id=v.product_id where p.design_reference in (select value->>'id' from jsonb_array_elements(release->'products'))),'[]'::jsonb),
    'inventory',coalesce((select jsonb_agg(to_jsonb(i)) from seen_private.inventory i join public.product_variants v on v.id=i.variant_id join public.products p on p.id=v.product_id where p.design_reference in (select value->>'id' from jsonb_array_elements(release->'products'))),'[]'::jsonb)
  );
  position_value:=0;
  for item in select value from jsonb_array_elements(release->'products') loop
    photo_list:=item->'photos';
    select id,photos into pid,existing_photos from public.products where design_reference=item->>'id';
    for extra in select value from jsonb_array_elements(coalesce(existing_photos,'[]'::jsonb)) loop
      if not exists(select 1 from jsonb_array_elements(photo_list) ph where ph->>'src'=extra->>'src') then
        photo_list:=photo_list||jsonb_build_array(extra);
      end if;
    end loop;
    if jsonb_array_length(photo_list)>12 then raise exception 'Too many combined photos for %. Review existing uploads first.',item->>'id'; end if;
    insert into public.products(design_reference,name,description,price_pence,status,details_confirmed,sort_order,photos,tone)
    values(item->>'id',item->>'name',item->>'description',(item->>'pricePence')::integer,'draft',false,position_value,photo_list,item->>'tone')
    on conflict(design_reference) do update set
      name=excluded.name,description=excluded.description,price_pence=coalesce(excluded.price_pence,public.products.price_pence),
      status='draft',details_confirmed=false,sort_order=excluded.sort_order,photos=excluded.photos,tone=excluded.tone
    returning id into pid;
    -- Retire old sample lengths without deleting IDs referenced by existing orders.
    update public.product_variants set active=false where product_id=pid;
    update seen_private.inventory set on_hand=0 where variant_id in (select id from public.product_variants where product_id=pid);
    for size_value in select value from jsonb_array_elements_text(release->'sizes') loop
      select id into vid from public.product_variants where product_id=pid and lower(size_label)=lower(size_value);
      if vid is null then
        insert into public.product_variants(product_id,size_label,sku,active,sort_order)
        values(pid,size_value,'SEEN-'||upper(item->>'id')||'-'||size_value,true,size_value::integer) returning id into vid;
      else
        update public.product_variants set active=true,sort_order=size_value::integer where id=vid;
      end if;
      insert into seen_private.inventory(variant_id,on_hand) values(vid,(item->'stock'->>size_value)::integer)
      on conflict(variant_id) do update set on_hand=excluded.on_hand;
    end loop;
    if (item->>'ready')::boolean then
      update public.products set status='published',details_confirmed=true where id=pid;
    end if;
    position_value:=position_value+1;
  end loop;
  insert into seen_private.admin_audit(action,entity,entity_id) values('import','catalog',release->>'batch');
end $import$;
commit;

-- SQL Editor verification only; exact quantities remain private to the backend.
select p.design_reference,p.name,p.price_pence,p.status,jsonb_agg(jsonb_build_object(
  'size',v.size_label,'on_hand',i.on_hand,'reserved',i.reserved
) order by v.sort_order) as sizes
from public.products p join public.product_variants v on v.product_id=p.id and v.active
join seen_private.inventory i on i.variant_id=v.id
where p.design_reference in ('design-01','design-02','design-03','design-04','design-05','design-06','design-07','design-08','design-09')
group by p.id order by p.sort_order;
